{{
  (() => {
    const normalize = (val) => {
      const s = String(val || "").trim().toLowerCase();
      if (!s) return "";
      if (s === "proveedor" || s === "proveedores") return "proveedores";
      if (s === "sueldo" || s === "sueldos") return "sueldos";
      if (s === "gasto fijo" || s === "gastos fijos") return "gastos fijos";
      return s;
    };

    const unicos = Array.from(
      new Set(
        (Select_public_gastos1.data || [])
          .map(r => normalize(r.sector))
          .filter(Boolean)
      )
    );

    return [
      { label: "Todos", value: "" },
      ...unicos.map(v => ({ label: v, value: v }))
    ];
  })()
}}
